def totalWindowRange(nums, k):
    from collections import deque
    mx = deque()
    mn = deque()
    total = 0
    for i, x in enumerate(nums):
        while mx and nums[mx[-1]] <= x:
            mx.pop()
        mx.append(i)
        while mn and nums[mn[-1]] >= x:
            mn.pop()
        mn.append(i)
        if mx[0] <= i - k:
            mx.popleft()
        if mn[0] <= i - k:
            mn.popleft()
        if i >= k - 1:
            total += nums[mx[0]] - nums[mn[0]]
    return total
